import sys

def solve():
    data = sys.stdin.read().split()
    N = int(data[0])
    A = [int(x) for x in data[1:N+1]]

    # b[i] in {0,1} for i in 0..N-1 (cyclic)
    # Constraints:
    # - b[i] * b[(i+1) % N] == 0
    # - If A[i] == 0: b[(i-1) % N] + b[i] >= 1

    for b0 in (0, 1):
        for b1 in (0, 1):
            if b0 & b1:
                continue
            # Coverage check for index 1 (A[1])
            if N >= 2 and A[1] == 0 and (b0 + b1) < 1:
                continue
            # DP from i=2 to N-1, state = (b[i-1], b[i])
            states = {(b0, b1)}
            ok = True
            for i in range(2, N):
                ai = A[i]
                new_states = set()
                for (bp, bc) in states:
                    for bn in (0, 1):
                        if bc & bn:
                            continue
                        if ai == 0 and (bc + bn) < 1:
                            continue
                        new_states.add((bc, bn))
                states = new_states
                if not states:
                    ok = False
                    break
            if not ok:
                continue
            # Wraparound: check b[N-1] with b[0]=b0, and coverage of A[0]
            for (bp, bc) in states:
                if bc & b0:
                    continue
                if A[0] == 0 and (bc + b0) < 1:
                    continue
                print("Yes")
                return
    # Edge case N could be anything >=3; loop handles it.
    print("No")

solve()

